import { Context, Effect, Layer, Schema } from "effect"
import { resolve } from "node:path"

const ArchiveConfig = Schema.Struct({
  directory: Schema.String,
  retentionDays: Schema.Number,
  compress: Schema.Boolean
})

type ArchiveConfig = typeof ArchiveConfig.Type

export class ArchivePolicy extends Context.Service<ArchivePolicy, {
  readonly retentionDays: ArchiveConfig["retentionDays"]
  readonly compress: ArchiveConfig["compress"]
  readonly archiveRoot: string
}>()("archives/ArchivePolicy") {}

export const archivePolicyLayer = (input: unknown) =>
  Layer.effect(
    ArchivePolicy,
    Effect.gen(function*() {
      const config = yield* Schema.decodeUnknownEffect(ArchiveConfig)(input)
      const archiveRoot = resolve(config.directory)

      return {
        retentionDays: config.retentionDays,
        compress: config.compress,
        archiveRoot
      }
    })
  )

export const planArchive = (batchId: string, createdAt: Date) =>
  Effect.gen(function*() {
    const policy = yield* ArchivePolicy
    const extension = policy.compress ? ".tar.gz" : ".tar"
    const expiresAt = new Date(
      createdAt.getTime() + policy.retentionDays * 24 * 60 * 60 * 1000
    )

    return {
      destination: resolve(policy.archiveRoot, `${batchId}${extension}`),
      expiresAt,
      compression: policy.compress ? "gzip" as const : "none" as const
    }
  })

